    if not lst:
        return []

    sorted_lst = sorted(lst)
    odd_indices = sorted_lst[::2]
    even_indices = sorted_lst[1::2][::-1]

    result = [num for pair in zip(odd_indices, even_indices) for num in pair]

    if len(odd_indices) > len(even_indices):
        result.append(odd_indices[-1])

    return result

